#[path="base.rs"]mod base;
use base::{Context,choose_primes,polynomial_values};use base::direct::native::NativeContext;
use zopro_bn254::Fr;use zopro_core::fft::{Plan,denominator};use serde_json::json;
fn main(){let n=32768;let qs=choose_primes(n);let native=NativeContext::new(n,&qs);let root=Fr::root_of_unity(n).unwrap();let coset=Fr::from(7u64);let mut accepted=Plan::new(n,root,coset,denominator(n,coset).unwrap());accepted.prepare_euler_study();let(a,da)=polynomial_values(&[Fr::from(101u64),-Fr::ONE,Fr::from(37u64),Fr::from(11u64)],n);let(b,db)=polynomial_values(&[-Fr::from(137u64),Fr::from(71u64),Fr::ONE],n);let expected=(0..n).map(|i|(da[i]*b[i]+a[i]*db[i])*Fr::from(n as u64)).collect::<Vec<_>>();let mut checks=0;for workers in[16,32]{let pool=rayon::ThreadPoolBuilder::new().num_threads(workers).stack_size(512*1024).build().unwrap();let result=pool.install(||accepted.euler_product_study(a.clone(),b.clone()));assert_eq!(result,expected);let result=pool.install(||native.product(a.clone(),b.clone()));assert_eq!(result,expected);checks+=2*n;}assert_eq!(native.n(),n);let unused_parent_type=std::mem::size_of::<Context>();assert!(unused_parent_type>0);let out=json!({"complete":true,"domain":n,"worker_counts":[16,32],"coordinate_comparisons":checks,"native_output_coordinates":2*n,"original_accepted_FFT_output_coordinates":2*n,"original_accepted_field":"1200e63547baa41c299a48e3221f1cef85990b0369f17452dc12eb17045f9713","original_accepted_core":"9dc62928d2988dd5d9b59a18502c8c462ce13a670f6b58a5eae26e88fc8bdc7c","native_projection_and_shared_dot_implemented":true,"new_latency_claim":false,"new_proofs":0,"proof_ledger":29953,"production_changed":false,"adopted":false,"goal_achieved":false});std::fs::write("/home/ubuntu/src/zopro-perf-work/crt-euler-native176/qualification.json",serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");}
